@Component("brand-handler")
@ProcessingGroup("brand-processing-group")
public class BrandEventHandler {
	
	// core constructor
	BrandEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateBrandEvent
     */
    @EventHandler
    public void handle( CreateBrandEvent event) {
        entityManager.persist(new Brand(event.getBrandId(), event.getName(), event.getDescription(), event.getWebsite(), event.getMerchant(), event.getProducts()));
    }

    /*
     * @param	event UpdateBrandEvent
     */
    @EventHandler
    public Brand handle( UpdateBrandEvent event) {
    	entityManager.merge(new Brand(event.getBrandId(), event.getName(), event.getDescription(), event.getWebsite(), event.getMerchant(), event.getProducts()));
    }
    
    /*
     * @param	event DeleteBrandEvent
     */
    @EventHandler
    public void on( DeleteBrandEvent event) {
    	Brand entity = new Brand();
   
    	// ------------------------------------------
    	// apply the BrandId
    	// ------------------------------------------
    	entity.setBrandId( event.getBrandId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final BrandRepository brandEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(BrandEventHandler.class.getName());

}
